draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = 'black';

  // Draw door frame
  ctx.strokeRect(W/2 - 50, H/2 - 100, 100, 200);

  // Draw door
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t) * Math.PI / 4);
  ctx.fillRect(-25, -50, 50, 100);
  ctx.restore();

  // Draw handle
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 25, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
